prompt._raw_prompt:
"{
  "图像元数据与投影标准": {
    "数据类型": "360度等距柱状全景图",
    "投影几何": "完整球形等距柱状投影",
    "画布物理规格": "标准2比1宽高比",
    "期望渲染精度": "超高分辨率极清画质"
  },
  "核心场景空间构图": {
    "地理空间轴": "多洛米蒂山脉，布莱耶斯湖（Pragser Wildsee）核心区域，无人机湖心视角",
    "相机基准位置": "位于湖面的中心原点，一个无缝、环绕的视角点",
    "相机垂直高度": "湖面上方约2米高度，以获得开阔的360度视野",
    "视场角覆盖率": "水平360度全环绕，垂直180度完整穹顶（-90度到+90度）",
    "数学投影行为": "标准等距柱状投影，为VR渲染器确保左右、上下物理无缝拼接",
    "宏观气象环境": "黎明时分，天空清澈，空气中有几缕如纱般的薄雾，湖面静止如镜，完美反射周围景观",
    "光学景深控制": "全景深锁定，从前景的湖底细节到远景的山峰皆清晰可见"
  },
  "前景视觉元素与动态捕捉": {
    "前景主体视图": "全景底部（接近相机），极度清澈的绿松石色湖水，湖底的细腻鹅卵石、沉没的古老树枝和水草清晰可见。在全景的前方中央，几根巨大的、扭曲的古老树根和原木（类似image_0.png但位置更集中、更丰富）半淹没在水中，倒影清晰。在全景的右侧，有一个由几块木筏和系缆柱组成的更完整的、历史悠久的木制码头。
    "动态时间线行为": "静态锁定，确保整个场景的宁静和倒影的完美。
    "物理真度约束": "完全遵循现实世界物理规律，光影、材质、比例与重力关系自然，水下透射光自然。
  },
  "中景地貌与实体特征": {
    "地形地貌特征": "360度环绕着茂密的、深绿色的针叶林（松树和杉树）。在全景的后方（左侧和中心），是壮丽、陡峭的石灰岩山脉（布莱耶斯山，类似image_0.png但山脉链更连绵），山顶被金色和粉色的黎明光线（阿尔卑斯之光）染色，山岩纹理清晰。其他方位的山脉则处于冷色调的黎明阴影中，山脊线连绵不绝。
    "建筑与村落基建": "在湖的远端（中景），一排红色的木制手划船（比image_0.png更多，位置更分散）系在不同的码头边。在远处的山脚下，可以看到一个小小的、传统的木质阿尔卑斯小木屋，有烟囱和木制露台。
    "大气粒子与云雾": "湖面上方有几缕极其纤细、如纱般的薄雾。天空中有几朵被金色黎明光线染红的高空卷云。
  },
  "远景环境与天空穹顶": {
    "远景边界景观": "连绵起伏、纹理丰富的多洛米蒂山脉链，环绕整个湖泊，山脊线在远方与天空交界。
    "天顶与天空表现": "完整的360度球形穹顶天空。在东方（日出方向），天空是金色的和粉色的，逐渐过渡到西方的深蓝色。天空中有几朵被黎明染红的卷云和几缕极高空的卷层云。一个金色的日出太阳刚刚从东方最远处的山脊后面升起，投下第一缕直射光。
  },
  "微观材质与物理表面特性": {
    "宏观材质特征": "材质具备细腻的微观纹理，严禁出现无细节、平滑无质感的计算机生成表面。沉没的树根呈现风化、苔藓覆盖的质感；湖底鹅卵石大小不一、形状各异；木制码头有裂纹和磨损迹象；山石有风蚀和冰川擦痕。
    "物理使用痕迹": "微小自然磨损、风化、风蚀或历史痕迹，强力增强画面现实主义质感。
    "纹理随机性分布": "纹理采用非周期性、自然随机分布算法，彻底避免规律性重复贴图痕迹，确保整个360度范围内的自然性。
  },
  "高动态范围光影渲染控制": {
    "主光源物理逻辑": "全局统一自然光照明，主光源是位于东方的日出太阳。光照方向清晰地投射在东面山峰上，产生鲜艳的金色和粉色高光。西面山峰和湖面的大部分区域处于冷色调的黎明阴影中。阴影方向与太阳位置一致。
    "阴影微观细节": "阴影边缘具备自然的物理软过渡，避免人工过度锐化。
    "环境反射与反弹光": "由于极度清澈的湖水和高光山峰，湖面上的倒影具有极高的保真度，将山峰的金色、粉色、以及森林的深绿色、天空的蓝色完美呈现。水下也接收到微妙的环境反弹光，呈现出湖水特有的绿松石色。
    "高光溢出控制": "东面山峰上的金色高光区域严格保留岩石材质纹理，严禁产生死白过曝现象。
  },
  "三维空间真实感与透视一致性": {
    "物体尺度关系": "所有物体严格遵循现实世界的比例尺，空间体量逻辑完全合理。前景的树根与中景的船、远景的山峰在体量上形成合理的视觉序列。
    "透视几何一致性": "环形空间结构连贯，无任何多视点透视冲突或几何畸变错误，在全景浏览器中浏览时线条流畅。
    "空气透视效应": "远景依物理规律轻微降低对比度与色彩饱和度，完美呈现深邃的空间深度感。
    "细节距离衰减": "视觉细节随距离增加自然衰减，保持整体画面的层次清晰度。
  },
  "全景边界无缝拼接约束": {
    "边界物理连续性": "画布最左侧边缘与最右侧边缘实现几何级无缝拼接，图形结构完美连贯（例如，同一座山峰被分割在左右两端，拼接后是一个完整的山峰）。
    "环形空间结构": "空间呈现绝对的环形闭合结构，家具、建筑、景观围绕中心原点均匀展开。
    "视觉断层绝对封杀": "左右两端色彩、光照、线条结构高度一致，图形拼接处无任何空间跳跃与视差断层。上下边界（南极和北极）也必须平滑过渡，无伪影。
  },
  "空间几何结构锁定规则": {
    "微观结构边缘": "物体物理边缘略有不完美，以增强写实摄影感。
    "拼接控制点": "拼接交界处过渡自然，严禁产生任何线条断裂、错位或图像重影。
    "物理接触阴影": "所有物体与地面或接触面相交处（如树根与湖底，码头与湖水），必须产生细腻的接触阴影，消除悬浮感。
  },
  "表面反射与环境映射": {
    "物理反射类型": "严格根据材质属性物理区分镜面反射与漫反射。湖面是镜面反射，但允许微妙的水波和薄雾引起的模糊；木材和岩石是漫反射。
    "表面粗糙度映射": "非绝对镜面材质的反射需呈现模糊物理漫反射，效果必须完全符合表面粗糙度设定。
    "环境闭环映射": "材质表面反射的内容必须与全景周围360度的环境闭环保持绝对一致。
  },
  "画面纯净度与人工痕迹过滤": {
    "瑕疵与噪点控制": "允许符合胶片或相机传感器的轻微自然瑕疵，严禁数字噪点、色彩断层与压缩痕迹。
    "无干扰视觉元素": "画面纯净，严禁出现水印、日期、文字、用户界面、人工边框或任何裁剪视窗。
    "全局风格一致性": "整体渲染风格、艺术调性横向360度完全统一，严禁任何局部的风格断层。
  },
  "专属场景控制路由": {
    "现代简约风格核心": "当识别为建筑或室内场景时，严格保持现代简约设计语汇，地板、墙体纹理连续，门窗结构完整不被切割。
    "写实摄影风格锁定": "当识别为自然或室外场景时，严格锁定写实摄影质感，避免任何现代建筑介入（除了描述的小木屋和码头），禁止电影感夸张光影，禁止奇幻与插画感。
  },
  "负面限制提示词矩阵": [
    "用户界面", "水印", "文字", "边框", "裁剪视图", 
    "全景接缝断裂", "拼缝不连续", "低画质", "噪点", 
    "现代建筑", "桥梁", "行人", "奇幻艺术", 
    "插图", "过度处理", "不连续的山脉", "悬浮物体", 
    "过曝日出", "不自然的倒影", "过多的游客船"
  ]
}
